  "revision_action": "strengthen",
  "supportive_card_ids": ["C29", "C02", "C17", "C21", "C62", "C46", "C52", "C38", "C57", "C61"],
  "contradictory_card_ids": ["C27", "C54", "C01", "C06", "C08", "C19", "C32", "C33", "C55", "C60", "C67", "C71"],
  "prediction_basis_card_ids": ["C29", "C02", "C17", "C21", "C62", "C46", "C52", "C38", "C57", "C61"],
  "claims": [
    {
      "claim": "C29 reports that the absolute bioavailability of a benzamidine-containing zwitterionic carboxylate is 'not high enough for oral use in humans'; this is the most transferable direct low-F outcome for the query's structural class (4-amidinobenzyl amide plus carboxylate/zwitterion).",
      "card_ids": ["C29"]
    },
    {
      "claim": "C62, C02, C17, and C21 report absolute oral bioavailability <3% for revefenacin, a fully ionized high-TPSA molecule; these reinforce that strongly ionized compounds in this evidence set can fall far below the 20% threshold.",
      "card_ids": ["C62", "C02", "C17", "C21"]
    },
    {
      "claim": "C46 and C52 report low oral bioavailability for emixustat in monkeys (18.4±15.2%) and rats (5.2±0.9%), a polar cyclohexyl-containing amine; this adds another low-F analog with a cyclohexyl group.",
      "card_ids": ["C46", "C52"]
    },
    {
      "claim": "C38, C57, and C61 report low oral bioavailability for sulpiride in rats (~15%), and C58 attributes sulpiride's poor oral bioavailability to low solubility, limited permeability, and P-gp efflux; although human sulpiride F is higher, the rat data support the poor-permeability pattern.",
      "card_ids": ["C38", "C57", "C61", "C58"]
    },
    {
      "claim": "C27 and C54 report 30±6% systemic availability of perindoprilat after oral perindopril in cirrhotic patients, but this is a prodrug-to-active-metabolite conversion, not the F of the zwitterionic diacid itself, and is less transferable to the query.",
      "card_ids": ["C27", "C54"]
    },
    {
      "claim": "The low-F outcomes in C29, C62, C46, and C52 are consistent with the query's strongly unfavorable passive-permeability prior (logD -7.48, TPSA 148.61, HBD 5, neutral fraction 0).",
      "card_ids": ["C29", "C62", "C46", "C52"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C62", "C46", "C52", "C38", "C57", "C61"]
    }
  ],
  "evidence_gaps": [
    "No direct experimental record for the query molecule itself was supplied; the decision relies on transferable analogs and the physicochemical prior.",
    "C29 provides only a qualitative low-F statement, not a numeric F value.",
    "No fasted-state-specific oral bioavailability measurement for the query is available.",
    "No data on active transport, efflux, or first-pass metabolism for the query were supplied.",
    "Human sulpiride and perindoprilat records show some ionized/zwitterionic molecules can exceed 20%, but their transferability is limited by structural and prodrug differences."
  ],
  "decision_summary": "Predicted low: the query is a fully ionized zwitterionic benzamidine peptidomimetic with very low logD and high TPSA; the most transferable L1 record (C29) reports absolute oral bioavailability 'not high enough for oral use in humans' for a structurally analogous benzamidine-containing zwitterion, and L2 adds further low-F records for ionized/cyclohexyl-containing molecules (C62, C46, C52, C38, C57, C61). Contradictory records (C27/C54, sulpiride human F) are less transferable or prodrug-based and do not outweigh the low evidence."
}

